@charset "UTF-8";
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;600;700&family=Noto+Serif+JP:wght@300;400;600&family=Plus+Jakarta+Sans:wght@300;400;500;600&display=swap');

/* ==========================================================================
   CSS Variables & Design Tokens
   ========================================================================== */
:root {
  --color-bg: #faf7f2;
  --color-bg-card: #ffffff;
  --color-bg-alt: #f3ede2;
  --color-primary: #382619;
  --color-primary-dark: #23160e;
  --color-accent: #c28f52;
  --color-accent-hover: #ad783d;
  --color-accent-light: #f6efe6;
  --color-text-main: #2d2621;
  --color-text-muted: #786d65;
  --color-text-light: #faf7f2;
  --color-border: #e6ded4;
  --color-border-focus: #c28f52;
  --color-badge-bg: #825a36;
  --color-badge-text: #ffffff;

  --font-serif: 'Cinzel', 'Noto Serif JP', serif;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --shadow-sm: 0 2px 8px rgba(56, 38, 25, 0.06);
  --shadow-md: 0 8px 24px rgba(56, 38, 25, 0.08);
  --shadow-lg: 0 16px 36px rgba(56, 38, 25, 0.12);
  --shadow-float: 0 20px 40px rgba(35, 22, 14, 0.2);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --transition-fast: 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-normal: 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

/* ==========================================================================
   Global Reset & Base
   ========================================================================== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg);
  color: var(--color-text-main);
  line-height: 1.7;
  overflow-x: hidden;
}

button {
  font-family: inherit;
  border: none;
  background: none;
  cursor: pointer;
  outline: none;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* ==========================================================================
   Main Application Wrap
   ========================================================================== */
.cafe-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
  background-color: var(--color-bg);
}

/* ==========================================================================
   Header & Navigation
   ========================================================================== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 72px;
  background: rgba(250, 247, 242, 0.92);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  z-index: 100;
  border-bottom: 1px solid rgba(230, 222, 212, 0.7);
  transition: all var(--transition-fast);
}

.header-container {
  max-width: 1200px;
  height: 100%;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand-logo {
  display: flex;
  flex-direction: column;
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--color-primary);
  line-height: 1.2;
}

.brand-sub {
  font-family: var(--font-sans);
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  color: var(--color-accent);
  text-transform: uppercase;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  list-style: none;
}

.nav-btn {
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--color-text-main);
  padding: 0.4rem 0.8rem;
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background-color var(--transition-fast);
  display: inline-flex;
  align-items: center;
}

.nav-btn:hover {
  color: var(--color-accent);
  background-color: rgba(194, 143, 82, 0.08);
}

/* ==========================================================================
   Hero Section
   ========================================================================== */
.hero-section {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-image: url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1920&q=80');
  background-position: center;
  background-size: cover;
  background-attachment: fixed;
  color: var(--color-text-light);
  padding: 6rem 1.5rem 4rem;
  overflow: hidden;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(35, 22, 14, 0.45) 0%,
    rgba(35, 22, 14, 0.7) 65%,
    rgba(35, 22, 14, 0.9) 100%
  );
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 820px;
  text-align: center;
  margin: 0 auto;
  animation: heroFadeIn 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes heroFadeIn {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.hero-tagline {
  display: inline-block;
  font-family: var(--font-serif);
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 1.25rem;
  padding: 0.25rem 1rem;
  border-top: 1px solid rgba(194, 143, 82, 0.6);
  border-bottom: 1px solid rgba(194, 143, 82, 0.6);
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.4rem, 5vw, 4.2rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 1.5rem;
  letter-spacing: 0.04em;
  text-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
}

.hero-desc {
  font-size: clamp(0.95rem, 1.8vw, 1.15rem);
  color: #e5ded7;
  max-width: 620px;
  margin: 0 auto 2.5rem;
  line-height: 1.9;
  font-weight: 300;
}

.hero-actions {
  display: flex;
  justify-content: center;
  gap: 1.25rem;
  flex-wrap: wrap;
}

/* ==========================================================================
   Buttons
   ========================================================================== */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background-color: var(--color-accent);
  color: #ffffff;
  padding: 0.9rem 2rem;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.95rem;
  letter-spacing: 0.05em;
  transition: all var(--transition-fast);
  box-shadow: 0 4px 14px rgba(194, 143, 82, 0.35);
  cursor: pointer;
  border: 1px solid var(--color-accent);
}

.btn-primary:hover {
  background-color: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(194, 143, 82, 0.45);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background-color: transparent;
  color: var(--color-text-light);
  padding: 0.9rem 2rem;
  border-radius: var(--radius-full);
  font-weight: 500;
  font-size: 0.95rem;
  letter-spacing: 0.05em;
  border: 1.5px solid rgba(255, 255, 255, 0.7);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.btn-secondary:hover {
  background-color: rgba(255, 255, 255, 0.15);
  border-color: #ffffff;
  transform: translateY(-2px);
}

/* ==========================================================================
   Shared Section Styles
   ========================================================================== */
.section-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 5rem 1.5rem;
}

.section-header {
  text-align: center;
  margin-bottom: 3.5rem;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  font-weight: 700;
  color: var(--color-primary);
  letter-spacing: 0.05em;
  margin-bottom: 0.5rem;
}

.section-subtitle {
  font-size: 0.92rem;
  font-weight: 400;
  letter-spacing: 0.1em;
  color: var(--color-accent);
  text-transform: uppercase;
}

/* ==========================================================================
   Concept / Feature Cards
   ========================================================================== */
.concept-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

.concept-card {
  background: var(--color-bg-card);
  padding: 2.75rem 2rem;
  border-radius: var(--radius-md);
  text-align: center;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
  transition: all var(--transition-normal);
  display: flex;
  flex-direction: column;
  align-items: center;
}

.concept-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
  border-color: rgba(194, 143, 82, 0.4);
}

.concept-icon {
  width: 64px;
  height: 64px;
  background-color: var(--color-accent-light);
  color: var(--color-accent);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8rem;
  margin-bottom: 1.5rem;
  transition: transform var(--transition-fast);
}

.concept-card:hover .concept-icon {
  transform: scale(1.1);
  background-color: var(--color-accent);
  color: #ffffff;
}

.concept-title {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 1rem;
}

.concept-text {
  font-size: 0.92rem;
  color: var(--color-text-muted);
  line-height: 1.8;
}

/* ==========================================================================
   Menu Section
   ========================================================================== */
.menu-section {
  background-color: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.category-tabs {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-bottom: 3rem;
}

.category-tab {
  padding: 0.65rem 1.4rem;
  font-size: 0.9rem;
  font-weight: 500;
  border-radius: var(--radius-full);
  background-color: var(--color-bg-card);
  color: var(--color-text-muted);
  border: 1px solid var(--color-border);
  transition: all var(--transition-fast);
}

.category-tab:hover {
  color: var(--color-primary);
  border-color: var(--color-accent);
}

.category-tab-active {
  background-color: var(--color-primary);
  color: #ffffff;
  border-color: var(--color-primary);
  box-shadow: 0 4px 12px rgba(56, 38, 25, 0.2);
}

.category-tab-active:hover {
  background-color: var(--color-primary);
  color: #ffffff;
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
}

.menu-card {
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
  transition: all var(--transition-normal);
  display: flex;
  flex-direction: column;
  position: relative;
}

.menu-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
}

.menu-card-badge {
  position: absolute;
  top: 1rem;
  right: 1rem;
  z-index: 2;
  background-color: var(--color-accent);
  color: #ffffff;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  padding: 0.25rem 0.65rem;
  border-radius: var(--radius-full);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
  text-transform: uppercase;
}

.menu-card-img {
  width: 100%;
  height: 200px;
  object-fit: cover;
  transition: transform 0.5s ease;
  background-color: #ddd;
}

.menu-card:hover .menu-card-img {
  transform: scale(1.05);
}

.menu-card-body {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.menu-card-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 0.5rem;
  gap: 0.5rem;
}

.menu-item-name {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-primary);
  line-height: 1.3;
}

.menu-item-en {
  font-size: 0.75rem;
  color: var(--color-accent);
  letter-spacing: 0.05em;
  margin-bottom: 0.75rem;
  font-weight: 500;
}

.menu-item-price {
  font-family: var(--font-serif);
  font-weight: 700;
  font-size: 1.15rem;
  color: var(--color-accent-hover);
  white-space: nowrap;
}

.menu-item-desc {
  font-size: 0.88rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin-bottom: 1.25rem;
  flex-grow: 1;
}

.menu-item-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: auto;
}

.menu-tag {
  font-size: 0.7rem;
  color: var(--color-text-muted);
  background-color: var(--color-bg-alt);
  padding: 0.2rem 0.6rem;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(230, 222, 212, 0.9);
}

/* ==========================================================================
   Access & Store Info Section
   ========================================================================== */
.access-section {
  background-color: var(--color-bg);
}

.access-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

.access-info-panel {
  background: var(--color-bg-card);
  padding: 2.5rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.info-row {
  display: flex;
  padding: 0.9rem 0;
  border-bottom: 1px solid var(--color-border);
}

.info-row:last-of-type {
  border-bottom: none;
  margin-bottom: 1.5rem;
}

.info-label {
  width: 110px;
  flex-shrink: 0;
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--color-primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.info-value {
  font-size: 0.88rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  flex-grow: 1;
}

.map-container {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.map-visual {
  position: relative;
  width: 100%;
  height: 380px;
  background-color: #e5ded5;
  background-image: 
    radial-gradient(#c28f52 0.75px, transparent 0.75px),
    linear-gradient(to right, rgba(215, 203, 190, 0.3) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(215, 203, 190, 0.3) 1px, transparent 1px);
  background-size: 20px 20px, 40px 40px, 40px 40px;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.map-marker {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  z-index: 2;
  cursor: pointer;
  animation: bounce 2s infinite ease-in-out;
}

@keyframes bounce {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-8px);
  }
}

.map-caption {
  font-size: 0.82rem;
  color: var(--color-text-muted);
  text-align: center;
  margin-top: 0.75rem;
}

/* ==========================================================================
   Reservation Modal & Form
   ========================================================================== */
.reservation-modal {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(35, 22, 14, 0.65);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

.modal-content {
  position: relative;
  z-index: 2;
  background: var(--color-bg-card);
  width: 100%;
  max-width: 540px;
  max-height: 90vh;
  overflow-y: auto;
  border-radius: var(--radius-lg);
  padding: 2.25rem;
  box-shadow: var(--shadow-float);
  border: 1px solid var(--color-border);
  animation: modalScaleUp 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes modalScaleUp {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.75rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--color-border);
}

.modal-header h3 {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--color-primary);
}

.modal-close-btn {
  font-size: 1.5rem;
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.modal-close-btn:hover {
  background-color: var(--color-bg-alt);
  color: var(--color-primary);
}

.form-group {
  margin-bottom: 1.25rem;
  display: flex;
  flex-direction: column;
}

.form-label {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 0.5rem;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.form-input,
.form-select,
.form-textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  font-family: inherit;
  font-size: 0.92rem;
  color: var(--color-text-main);
  background-color: #fff;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(194, 143, 82, 0.15);
}

.form-textarea {
  resize: vertical;
  min-height: 90px;
}

/* ==========================================================================
   Toast Notification
   ========================================================================== */
.toast-notification {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  z-index: 1100;
  background-color: var(--color-primary-dark);
  color: #ffffff;
  padding: 1rem 1.5rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border-left: 4px solid var(--color-accent);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.92rem;
  animation: toastSlideIn 0.35s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes toastSlideIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ==========================================================================
   Footer
   ========================================================================== */
.footer {
  background-color: var(--color-primary-dark);
  color: #c9bfb5;
  padding: 4rem 1.5rem 2rem;
  margin-top: auto;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.footer-content {
  max-width: 1200px;
  margin: 0 auto 3rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1.5rem;
}

.footer .brand-logo {
  color: #ffffff;
}

.footer .brand-sub {
  color: var(--color-accent);
}

.footer-copy {
  font-size: 0.8rem;
  letter-spacing: 0.05em;
  color: #8c8077;
  text-align: center;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding-top: 2rem;
}

/* ==========================================================================
   Responsive Adaptations
   ========================================================================== */
@media (max-width: 900px) {
  .access-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .map-visual {
    height: 300px;
  }
}

@media (max-width: 768px) {
  .header {
    height: 64px;
  }

  .nav-links {
    gap: 0.5rem;
  }

  .nav-btn {
    font-size: 0.8rem;
    padding: 0.3rem 0.5rem;
  }

  .section-container {
    padding: 3.5rem 1rem;
  }

  .section-header {
    margin-bottom: 2.25rem;
  }

  .hero-actions {
    flex-direction: column;
    width: 100%;
    max-width: 280px;
  }

  .btn-primary, .btn-secondary {
    width: 100%;
  }

  .toast-notification {
    left: 1rem;
    right: 1rem;
    bottom: 1rem;
  }

  .modal-content {
    padding: 1.5rem;
  }
}

@media (max-width: 480px) {
  .brand-logo {
    font-size: 1.1rem;
  }

  .brand-sub {
    font-size: 0.6rem;
  }

  .info-row {
    flex-direction: column;
    gap: 0.25rem;
  }

  .info-label {
    width: auto;
  }
}

export type MenuCategory = 'coffee' | 'drink' | 'food' | 'sweets';

export interface MenuItem {
  id: string;
  name: string;
  nameEn: string;
  category: MenuCategory;
  price: number;
  description: string;
  imageUrl: string;
  isRecommended?: boolean;
  isSeasonal?: boolean;
  tags: string[];
}

export interface CategoryOption {
  id: 'all' | MenuCategory;
  label: string;
}

export interface StoreInfo {
  name: string;
  address: string;
  postalCode: string;
  accessText: string;
  tel: string;
  hoursWeekday: string;
  hoursWeekend: string;
  closedDay: string;
  seats: string;
  facilities: string[];
}

export interface ReservationFormValues {
  name: string;
  email: string;
  phone: string;
  date: string;
  time: string;
  guests: number;
  requestNote: string;
}

export interface ConceptItem {
  id: string;
  icon: string;
  title: string;
  description: string;
}

import { useState } from 'react';
import { CategoryOption, MenuItem } from '../types';
import { CATEGORY_OPTIONS, MENU_ITEMS } from '../data';

export default function MenuSection() {
  const [selectedCategory, setSelectedCategory] = useState<CategoryOption['id']>('all');

  const filteredItems: MenuItem[] = selectedCategory === 'all'
    ? MENU_ITEMS
    : MENU_ITEMS.filter((item) => item.category === selectedCategory);

  return (
    <section id="menu" className="menu-section">
      <div className="section-container">
        <div className="section-header">
          <span className="section-subtitle">Our Offerings</span>
          <h2 className="section-title">メニューのご案内</h2>
        </div>

        <div className="category-tabs">
          {CATEGORY_OPTIONS.map((cat) => {
            const isActive = selectedCategory === cat.id;
            return (
              <button
                key={cat.id}
                type="button"
                className={isActive ? 'category-tab category-tab-active' : 'category-tab'}
                onClick={() => setSelectedCategory(cat.id)}
              >
                {cat.label}
              </button>
            );
          })}
        </div>

        <div className="menu-grid">
          {filteredItems.map((item) => (
            <article key={item.id} className="menu-card">
              {item.isRecommended && (
                <span className="menu-card-badge">おすすめ</span>
              )}
              {!item.isRecommended && item.isSeasonal && (
                <span className="menu-card-badge" style={{ backgroundColor: '#436154' }}>
                  季節限定
                </span>
              )}

              <img
                src={item.imageUrl}
                alt={item.name}
                className="menu-card-img"
                loading="lazy"
              />

              <div className="menu-card-body">
                <div className="menu-card-head">
                  <h3 className="menu-item-name">{item.name}</h3>
                  <span className="menu-item-price">¥{item.price.toLocaleString()}</span>
                </div>
                <div className="menu-item-en">{item.nameEn}</div>
                <p className="menu-item-desc">{item.description}</p>
                <div className="menu-item-tags">
                  {item.tags.map((tag) => (
                    <span key={tag} className="menu-tag">
                      #{tag}
                    </span>
                  ))}
                </div>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

import { useState } from 'react';
import HeaderHero from './components/HeaderHero';
import MenuSection from './components/MenuSection';
import AccessSection from './components/AccessSection';
import { CONCEPTS, STORE_INFO } from './data';
import { ReservationFormValues } from './types';

const INITIAL_FORM: ReservationFormValues = {
  name: '',
  email: '',
  phone: '',
  date: '',
  time: '14:00',
  guests: 2,
  requestNote: '',
};

export default function App() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<ReservationFormValues>(INITIAL_FORM);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const handleOpenReservation = () => {
    setIsModalOpen(true);
  };

  const handleCloseReservation = () => {
    setIsModalOpen(false);
  };

  const handleInputChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: name === 'guests' ? Number(value) : value,
    }));
  };

  const handleSubmitReservation = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.phone || !formData.date) {
      alert('お名前、電話番号、希望日は必須入力です。');
      return;
    }

    setIsModalOpen(false);
    setToastMessage(
      `【ご予約完了】${formData.name} 様、${formData.date} ${formData.time}（${formData.guests}名様）の予約を承りました。`
    );
    setFormData(INITIAL_FORM);

    setTimeout(() => {
      setToastMessage(null);
    }, 4500);
  };

  return (
    <div className="cafe-app">
      <HeaderHero onOpenReservation={handleOpenReservation} />

      {/* こだわり・コンセプト セクション */}
      <section id="concept" className="section-container">
        <div className="section-header">
          <span className="section-subtitle">Our Philosophy</span>
          <h2 className="section-title">L'OMBRE のこだわり</h2>
        </div>

        <div className="concept-grid">
          {CONCEPTS.map((concept) => (
            <article key={concept.id} className="concept-card">
              <div className="concept-icon">{concept.icon}</div>
              <h3 className="concept-title">{concept.title}</h3>
              <p className="concept-text">{concept.description}</p>
            </article>
          ))}
        </div>
      </section>

      {/* メニュー一覧 セクション */}
      <MenuSection />

      {/* 店舗情報・アクセス セクション */}
      <AccessSection onOpenReservation={handleOpenReservation} />

      {/* フッター */}
      <footer className="footer">
        <div className="footer-content">
          <div className="brand-logo">
            CAFE DE L'OMBRE
            <span className="brand-sub">Specialty Coffee & Kitchen</span>
          </div>
          <p style={{ maxWidth: '500px', fontSize: '0.88rem', lineHeight: '1.8' }}>
            {STORE_INFO.address}
            <br />
            営業時間: {STORE_INFO.hoursWeekday} / 定休日: {STORE_INFO.closedDay}
          </p>
        </div>
        <div className="footer-copy">
          &copy; {new Date().getFullYear()} CAFE DE L'OMBRE. All rights reserved.
        </div>
      </footer>

      {/* 予約モーダル */}
      {isModalOpen && (
        <div className="reservation-modal">
          <div className="modal-backdrop" onClick={handleCloseReservation} />
          <div className="modal-content">
            <div className="modal-header">
              <h3>お席のご予約</h3>
              <button
                type="button"
                className="modal-close-btn"
                onClick={handleCloseReservation}
                aria-label="閉じる"
              >
                &times;
              </button>
            </div>

            <form onSubmit={handleSubmitReservation}>
              <div className="form-group">
                <label className="form-label" htmlFor="name">
                  お名前 <span style={{ color: '#d9534f' }}>*</span>
                </label>
                <input
                  id="name"
                  name="name"
                  type="text"
                  required
                  placeholder="山田 太郎"
                  className="form-input"
                  value={formData.name}
                  onChange={handleInputChange}
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="phone">
                  お電話番号 <span style={{ color: '#d9534f' }}>*</span>
                </label>
                <input
                  id="phone"
                  name="phone"
                  type="tel"
                  required
                  placeholder="090-1234-5678"
                  className="form-input"
                  value={formData.phone}
                  onChange={handleInputChange}
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="email">
                  メールアドレス
                </label>
                <input
                  id="email"
                  name="email"
                  type="email"
                  placeholder="example@cafe-ombre.jp"
                  className="form-input"
                  value={formData.email}
                  onChange={handleInputChange}
                />
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                <div className="form-group">
                  <label className="form-label" htmlFor="date">
                    ご来店日 <span style={{ color: '#d9534f' }}>*</span>
                  </label>
                  <input
                    id="date"
                    name="date"
                    type="date"
                    required
                    className="form-input"
                    value={formData.date}
                    onChange={handleInputChange}
                  />
                </div>

                <div className="form-group">
                  <label className="form-label" htmlFor="time">
                    時間帯
                  </label>
                  <select
                    id="time"
                    name="time"
                    className="form-select"
                    value={formData.time}
                    onChange={handleInputChange}
                  >
                    <option value="09:00">09:00 (モーニング)</option>
                    <option value="11:30">11:30 (ランチ)</option>
                    <option value="13:00">13:00 (ランチ)</option>
                    <option value="14:30">14:30 (カフェ)</option>
                    <option value="16:00">16:00 (カフェ)</option>
                    <option value="18:00">18:00 (ディナー)</option>
                    <option value="19:00">19:00 (ディナー)</option>
                  </select>
                </div>
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="guests">
                  ご利用人数
                </label>
                <select
                  id="guests"
                  name="guests"
                  className="form-select"
                  value={formData.guests}
                  onChange={handleInputChange}
                >
                  <option value={1}>1名様（カウンター席・テーブル席）</option>
                  <option value={2}>2名様（テーブル席）</option>
                  <option value={3}>3名様（テーブル席）</option>
                  <option value={4}>4名様（ゆったりソファ席）</option>
                  <option value={5}>5名様〜（個室または結合席）</option>
                </select>
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="requestNote">
                  ご要望・アレルギー・テラス席希望など
                </label>
                <textarea
                  id="requestNote"
                  name="requestNote"
                  placeholder="例：テラス席でペット同伴希望、乳製品アレルギーあり 等"
                  className="form-textarea"
                  value={formData.requestNote}
                  onChange={handleInputChange}
                />
              </div>

              <button
                type="submit"
                className="btn-primary"
                style={{ width: '100%', marginTop: '0.75rem' }}
              >
                予約内容を送信する
              </button>
            </form>
          </div>
        </div>
      )}

      {/* 完了通知トースト */}
      {toastMessage && (
        <aside className="toast-notification">
          <span>✓</span>
          <span>{toastMessage}</span>
        </aside>
      )}
    </div>
  );
}
